30	// Creates a temp dir and registers cleanup for the calling suite.
31	export function tempDir() {
32	  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'jsonpatch-cli-'));
33	  after(() => {
34	    fs.rmSync(dir, { recursive: true, force: true });
35	  });
36	  return dir;
37	}
38	
39	export function writeFile(dir, name, content) {
40	  const p = path.join(dir, name);
41	  fs.writeFileSync(p, content);
42	  return p;
43	}
44	
45	export function assertFailure(r, exitCode, line) {
46	  assert.equal(r.status, exitCode);
47	  assert.equal(r.stdout, '');
48	  assert.equal(r.stderr, line + '\n');
49	}
50	
51	export function assertSuccess(r, value) {
52	  assert.equal(r.status, 0);
53	  assert.equal(r.stderr, '');
54	  assert.equal(r.stdout, JSON.stringify(value, null, 2) + '\n');
55	}
56	
57	// Valid JSON '[]' padded with trailing spaces so that prefix + content is `total` bytes.
58	export function padded(total, prefix = Buffer.alloc(0)) {
59	  const body = Buffer.from('[]');
60	  const fill = Buffer.alloc(total - prefix.length - body.length, 0x20);
61	  return Buffer.concat([prefix, body, fill]);
62	}
