1	// parsePointer: decoding, validation and error types (spec: Pointers).
2	import { describe, test } from 'node:test';
3	import assert from 'node:assert/strict';
4	import { parsePointer } from '../jsonpatch.mjs';
5	
6	function assertSyntaxError(pointer) {
7	  assert.throws(
8	    () => parsePointer(pointer),
9	    (err) => {
10	      assert.ok(err instanceof SyntaxError, 'must be a SyntaxError');
11	      assert.ok(!(err instanceof TypeError), 'must not be a TypeError');
12	      assert.equal(err.message, 'invalid pointer');
13	      return true;
14	    },
15	  );
16	}
17	
18	function assertTypeError(pointer) {
19	  assert.throws(
20	    () => parsePointer(pointer),
21	    (err) => {
22	      assert.ok(err instanceof TypeError, 'must be a TypeError');
23	      assert.ok(!(err instanceof SyntaxError), 'must not be a SyntaxError');
24	      assert.equal(err.message, 'pointer must be a string');
25	      return true;
26	    },
27	  );
28	}
29	
30	describe('parsePointer: token splitting', () => {
31	  const cases = [
32	    ['the empty string has no tokens', '', []],
33	    ['"/" has one empty token', '/', ['']],
34	    ['empty tokens in the middle and at the end are kept', '/a//b/', ['a', '', 'b', '']],
35	    ['plain tokens are split on slash', '/a/b', ['a', 'b']],
36	    ['a single token', '/a', ['a']],
37	    ['two empty tokens', '//', ['', '']],
38	    ['a leading empty token', '//a', ['', 'a']],
39	    ['a space is an ordinary character', '/ a', [' a']],
40	    ['a token with trailing space', '/a /b', ['a ', 'b']],
41	    ['digits are plain tokens', '/0/01/-', ['0', '01', '-']],
42	    ['__proto__ is an ordinary token', '/__proto__/constructor', ['__proto__', 'constructor']],
43	  ];
44	  for (const [name, pointer, expected] of cases) {
45	    test(name, () => {
46	      assert.deepEqual(parsePointer(pointer), expected);
47	    });
48	  }
49	});
50	
51	describe('parsePointer: escape decoding', () => {
52	  const cases = [
53	    ['~01 decodes to the two characters ~1 (not to a slash)', '/~01', ['~1']],
54	    ['~10 decodes to a slash followed by 0 (not to a tilde)', '/~10', ['/0']],
55	    ['~0~1 decodes to tilde then slash', '/~0~1', ['~/']],
56	    ['~1~0 decodes to slash then tilde', '/~1~0', ['/~']],
57	    ['~00 decodes to tilde followed by 0', '/~00', ['~0']],
58	    ['~11 decodes to slash followed by 1', '/~11', ['/1']],
59	    ['~0 alone decodes to a tilde', '/~0', ['~']],
60	    ['~1 alone decodes to a slash and does not split', '/~1', ['/']],
61	    ['escapes inside several tokens', '/a~1b/c~0d', ['a/b', 'c~d']],
62	    ['an escape followed by a separator', '/~1/~0', ['/', '~']],
63	    ['a tilde escape at token end followed by empty token', '/~0/', ['~', '']],
64	  ];
65	  for (const [name, pointer, expected] of cases) {
66	    test(name, () => {
67	      assert.deepEqual(parsePointer(pointer), expected);
68	    });
69	  }
70	});
71	
72	describe('parsePointer: characters are kept exactly', () => {
73	  test('non-ASCII characters are kept as they are', () => {
74	    assert.deepEqual(parsePointer('/é/日本'), ['é', '日本']);
75	  });
76	
77	  test('control characters NUL, LF and CR are kept as they are', () => {
78	    const tokens = parsePointer('/\u0000\n\r');
79	    assert.equal(tokens.length, 1);
80	    assert.equal(tokens[0], '\u0000\n\r');
81	    assert.equal(tokens[0].length, 3);
