84	  test('decomposed e + combining accent is not normalized', () => {
85	    const tokens = parsePointer('/é');
86	    assert.equal(tokens.length, 1);
87	    assert.equal(tokens[0].length, 2);
88	    assert.equal(tokens[0], 'é');
