105	describe('parsePointer: returns a new array', () => {
106	  test('mutating a result does not affect the next call', () => {
107	    const first = parsePointer('/a/b');
108	    first.push('x');
109	    first[0] = 'changed';
110	    assert.deepEqual(parsePointer('/a/b'), ['a', 'b']);
