135	describe('parsePointer: invalid pointers throw SyntaxError "invalid pointer"', () => {
136	  const cases = [
137	    ['a non-empty pointer must start with a slash: "a"', 'a'],
138	    ['a fragment form is not a pointer: "#/a"', '#/a'],
139	    ['a leading space is not allowed: " /a"', ' /a'],
140	    ['a lone tilde', '~'],
141	    ['a tilde at the end of the token after slash', '/~'],
142	    ['a tilde at the end of a later token', '/a~'],
143	    ['~2 is not an escape', '/~2'],
144	    ['~a is not an escape', '/~a'],
145	    ['~~ is not an escape', '/~~'],
146	    ['a tilde followed by a separator', '/~/'],
