159	describe('parsePointer: non-strings throw TypeError "pointer must be a string"', () => {
160	  const cases = [
161	    ['undefined', undefined],
162	    ['null', null],
163	    ['the number 0', 0],
164	    ['the number 1', 1],
165	    ['true', true],
166	    ['false', false],
167	    ['a String object with a path', new String('/a')],
168	    ['an empty String object', new String('')],
169	    ['an array holding a pointer', ['/a']],
170	    ['an empty array', []],
171	    ['an empty object', {}],
172	    ['a symbol', Symbol('x')],
173	    ['a function', function pointer() {}],
174	    ['an arrow function', () => '/a'],
175	    ['a bigint', 1n],
176	    ['NaN', NaN],
177	  ];
178	  for (const [name, value] of cases) {
179	    test(`rejects ${name}`, () => assertTypeError(value));
180	  }
181	
182	  test('an object with a toString returning a pointer is still rejected', () => {
183	    assertTypeError({ toString: () => '/a' });
184	  });
185	
186	  test('called with no argument it is rejected', () => {
187	    assert.throws(
188	      () => parsePointer(),
189	      (err) => err instanceof TypeError && err.message === 'pointer must be a string',
190	    );
191	  });
192	});
