1	// applyPatch: patch shape, form rules, their precedence and error shape (spec: Patches, Form rules, Errors).
2	import { describe, test } from 'node:test';
3	import assert from 'node:assert/strict';
4	import { applyPatch, PatchError } from '../jsonpatch.mjs';
5	import { assertExact, assertPatchError, assertNoSharing } from './helpers.mjs';
6	
7	const ok = (op) => ({ op: 'test', path: '', value: {} });
8	const validOps = () => [ok(), ok()];
9	
10	// An object with the given own members, none inherited.
11	const own = (members) => Object.assign(Object.create(null), members);
12	
13	// An operation whose `name` member is own but not enumerable.
14	function hidden(base, name, value) {
15	  const op = { ...base };
16	  delete op[name];
17	  return Object.defineProperty(op, name, { value, enumerable: false, writable: true, configurable: true });
18	}
19	
20	// Asserts a form error at index 0 and, after two valid ops, at index 2.
21	function assertFormError(bad, reason) {
22	  assertPatchError({}, [bad], `operation 0: ${reason}`, 0);
23	  assertPatchError({}, [...validOps(), bad], `operation 2: ${reason}`, 2);
24	}
25	
26	describe('patch must be an array', () => {
27	  const cases = [
28	    ['undefined', undefined],
29	    ['null', null],
30	    ['a plain object', {}],
31	    ['a string "[]"', '[]'],
32	    ['the number 0', 0],
33	    ['an array-like with length 0', { length: 0 }],
34	    ['a Uint8Array', new Uint8Array(0)],
35	    ['an arguments-like object', { 0: { op: 'test', path: '', value: 1 }, length: 1 }],
36	    ['true', true],
37	    ['a function', () => []],
38	  ];
39	  for (const [name, patch] of cases) {
40	    test(`${name} gives "patch must be an array" with index null`, () => {
41	      assertPatchError({ a: 1 }, patch, 'patch must be an array', null);
42	    });
43	  }
44	
45	  test('an empty array is fine and returns a copy of the document', () => {
46	    const doc = { a: [1, { b: -0 }] };
47	    const result = applyPatch(doc, []);
48	    assertExact(result, { a: [1, { b: -0 }] });
49	    assertNoSharing(result, doc);
50	  });
51	});
52	
53	describe('PatchError shape', () => {
54	  function catchError(patch) {
55	    try {
56	      applyPatch({}, patch);
57	    } catch (err) {
58	      return err;
59	    }
60	    return assert.fail('nothing thrown');
61	  }
62	
63	  test('a form error is a PatchError and an Error named PatchError', () => {
64	    const err = catchError([{ op: 'nope' }]);
65	    assert.ok(err instanceof PatchError);
66	    assert.ok(err instanceof Error);
67	    assert.equal(err.name, 'PatchError');
68	    assert.equal(err.message, 'operation 0: bad op');
69	    assert.equal(typeof err.index, 'number');
70	    assert.equal(err.index, 0);
71	  });
72	
73	  test('a non-array error is a PatchError with index exactly null', () => {
74	    const err = catchError(undefined);
75	    assert.ok(err instanceof PatchError);
76	    assert.ok(err instanceof Error);
77	    assert.equal(err.name, 'PatchError');
78	    assert.equal(err.index, null);
79	    assert.notEqual(err.index, undefined);
80	    assert.ok(Object.hasOwn(err, 'index'));
81	  });
82	
83	  test('an apply error also carries a numeric index', () => {
84	    const err = catchError([ok(), { op: 'remove', path: '/zz' }]);
85	    assert.ok(err instanceof PatchError);
86	    assert.equal(typeof err.index, 'number');
87	    assert.equal(err.index, 1);
88	    assert.equal(err.message, 'operation 1: path not found');
89	  });
90	});
91	
92	describe('not an object', () => {
93	  const fn = () => {};
94	  const fnWithMembers = Object.assign(() => {}, { op: 'add', path: '/a', value: 1 });
95	  const cases = [
96	    ['null', null],
97	    ['undefined', undefined],
98	    ['a number', 1],
99	    ['a string', 'add'],
100	    ['true', true],
101	    ['an empty array', []],
102	    ['an array holding an operation', [{ op: 'add' }]],
103	    ['a function', fn],
104	    ['a function with own op, path and value', fnWithMembers],
105	    ['a symbol', Symbol('op')],
106	    ['a bigint', 1n],
107	  ];
108	  for (const [name, bad] of cases) {
109	    test(`${name} is "not an object" at index 0 and index 2`, () => assertFormError(bad, 'not an object'));
110	  }
111	
112	  test('a hole in a one-element array is "not an object" at index 0', () => {
113	    assertPatchError({}, new Array(1), 'operation 0: not an object', 0);
114	  });
115	
116	  test('a trailing hole after a valid op is "not an object" at index 1', () => {
117	    // eslint-disable-next-line no-sparse-arrays
118	    assertPatchError({}, [{ op: 'test', path: '', value: {} }, ,], 'operation 1: not an object', 1);
119	  });
120	
121	  test('a hole in the middle is "not an object" at index 1', () => {
122	    const patch = [ok(), , ok()];
123	    assertPatchError({}, patch, 'operation 1: not an object', 1);
124	  });
125	});
126	
127	describe('objects that are not plain still go on to the next rule', () => {
128	  test('a String object has no own op: "bad op"', () => {
129	    assertFormError(new String('x'), 'bad op');
130	  });
131	
132	  test('a Date has no own op: "bad op"', () => {
133	    assertFormError(new Date(0), 'bad op');
134	  });
135	
136	  test('a Date with own op, path and value is applied', () => {
137	    const op = Object.assign(new Date(0), { op: 'add', path: '/a', value: 1 });
138	    assertExact(applyPatch({}, [op]), { a: 1 });
139	  });
140	
141	  test('a String object with own op, path and value is applied', () => {
142	    const op = Object.assign(new String('s'), { op: 'add', path: '/a', value: 1 });
143	    assertExact(applyPatch({}, [op]), { a: 1 });
144	  });
145	
146	  test('an object without a prototype is applied', () => {
147	    const op = own({ op: 'add', path: '/a', value: 1 });
148	    assertExact(applyPatch({}, [op]), { a: 1 });
149	  });
